SELECT mpl.ID, mpl.FACTORY_CODE, mpl.PRODUCT_TYPE_CODE, mpl.PRODUCT_CODE, mpl.A_LEVEL, mpi.BRAND, mpl.REMARK, mpl.IS_DELETE, mpl.CREATE_TIME, mpl.UPDATE_TIME, mpl.CREATE_BY, mpl.UPDATE_BY FROM T_MDM_PRODUCT_A_LEVEL mpl LEFT JOIN t_mdm_product_info mpi ON mpi.PRODUCT_CODE = mpl.PRODUCT_CODE AND mpi.FACTORY_CODE = mpl.FACTORY_CODE WHERE IFNULL(mpl.IS_DELETE,0) = 0
AND mpl.FACTORY_CODE = #{factoryCode}
AND mpl.PRODUCT_TYPE_CODE = #{productTypeCode}

