UPDATE t_mdm_stock_up_plan stockUp SET stockUp.STOCK_QTY = 0, stockUp.UPDATE_TIME = NOW()
WHERE stockUp.`YEAR` = #{year} AND stockUp.`MONTH` = #{month}
AND EXISTS(
    SELECT 1 FROM T_MDM_PRODUCT_A_LEVEL mpl
    WHERE mpl.FACTORY_CODE = stockUp.FACTORY_CODE AND mpl.PRODUCT_CODE = stockUp.PRODUCT_CODE

        AND mpl.ID IN

            #{item}


)
